files.templates/competitor-intelligence-analys:
{
  "schema_version": 1,
  "template_id": "competitor-intelligence-analyst",
  "template_version": 1,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm marketing role and owner",
      "instructions": "Confirm whether Competitor Intelligence Analyst is this Crew’s primary role or an added capability. Preserve existing identity and name the accountable owner."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/competitor-intelligence-analyst/SKILL.md exists and competitor-intelligence-analyst is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Set exact job and measurement scope",
      "instructions": "Record offer, market, campaign or experiment identity, period and time zone, owner, allowed sources, and first job. Minimum input: Own offer and buyer, approved competitor/product list, watch topics, source scope, comparison baseline, time window, alert threshold, and owner."
    },
    {
      "id": "access",
      "title": "Probe representative source access",
      "instructions": "Read one actual authorized source or export. Record stable IDs, revisions, timestamps, denominator or baseline coverage, and missing access. Public vendor pages and changelogs, approved research sources, CRM win/loss notes, and a saved source snapshot through browser or scoped MCP; a bounded URL set supports a read-only first brief."
    },
    {
      "id": "policy",
      "title": "Confirm evidence and action boundary",
      "instructions": "Record comparable metric definitions, citation and privacy rules, approval owner, alert or decision threshold, and exact action boundary. Do not scrape behind access controls, copy protected customer data, claim market share, change prices, publish claims, or contact a competitor from installation."
    },
    {
      "id": "first_result",
      "title": "Produce first sourced result",
      "instructions": "Use real authorized input to produce A dated change brief with exact competitor/product/plan, primary source and capture time, prior-versus-current evidence, relevance, uncertainty, and owner question. Each change needs before/after source IDs and capture times, or an explicit baseline gap; a copied claim is not independent verification. Fictional examples do not complete this check."
    },
    {
      "id": "review",
      "title": "Review result with owner",
      "instructions": "Show calculations, source coverage, uncertainty, proposed decision, and owner correction. Record the review decision."
    },
    {
      "id": "delivery",
      "title": "Choose read-only or action route",
      "optional": true,
      "instructions": "Choose read-only chat or a separately authorized campaign, page, experiment, report, or contact write route. Read-only completes this choice."
    },
    {
      "id": "recurrence",
      "title": "Choose repeat rule",
      "optional": true,
      "instructions": "Choose manual-only or a reviewed event/schedule with stable IDs, deduplication, cost, and notifications. Manual-only completes this choice. Retain watched URL/product keys and prior captures, compare only changed facts, recheck expiring prices and terms, and suppress unchanged alerts."
    }
  ],
  "completed_steps": []
}

